export type StudyQuestion = { prompt: string; answer: string; choices?: string[]; correct?: number };
export type StudyLesson = {
  id: string; title: string; focus: string; read: string[]; vocabulary: [string, string][];
  activity: string; coach: string; misconception: string; stretch: string; questions: StudyQuestion[];
};
export type StudyUnit = { id: string; subject: 'science' | 'social'; title: string; label: string; status: string; description: string; note?: string; sources: string[]; lessons: StudyLesson[] };
