const mc = (prompt: string, choices: string[], correct: number, answer: string): StudyQuestion => ({ prompt, choices, correct, answer });
const write = (prompt: string, answer: string): StudyQuestion => ({ prompt, answer });
export const studyUnits: StudyUnit[] = [
  { id: 'matter', subject: 'science', title: 'Modeling Matter', label: 'Unit 2', status: 'Start here', description: 'Become a food scientist. Explain mixtures using particles too small to see.', note: 'The published Amplify guide has 3 chapters. Section 4 below is an original home review, not an official Amplify chapter. Classroom editions may group lessons differently.', sources: ['matter', 'amplify'], lessons: [
    { id: 'matter-1', title: 'Chapter 1 · Separating mixtures', focus: 'How can a single color contain several dyes?', read: [
      'A bowl of rice and beans is a mixture: two materials together. You can separate them by a property such as size. Some mixtures look like one material even though several substances are present. A green coloring, for example, may contain yellow and blue dyes.',
      'In paper chromatography, water moves through paper and carries dye particles. Different dyes interact differently with the water and paper, so they can travel different distances. Separate bands provide evidence that more than one dye was present. A particle model uses symbols for tiny particles; the symbols are not their actual colors or sizes.'
    ], vocabulary: [['matter', 'Anything that has mass and takes up space.'], ['mixture', 'Two or more substances combined.'], ['property', 'A characteristic we can observe or measure.'], ['chromatography', 'A way to separate a mixture as its parts move differently through a material.']], activity: 'With an adult, put a dot of washable, water-soluble marker on a coffee-filter strip about 2 cm above the bottom. Stand just the bottom in a little water; keep the dot above the water. Watch for 5–10 minutes. Record colors and distances. Some markers will not separate; that result alone does not prove the ink is a pure substance. Do not taste materials.', coach: 'Ask what was observed before asking why it happened. Then ask your child to draw water particles and two kinds of dye particles, using a key. Ask how the drawing explains the bands.', misconception: 'Water does not create new dyes. It helps separate dyes already mixed in the ink. Bigger bands do not automatically mean bigger molecules.', stretch: 'Compare two washable markers using identical strips, water depth, and time. Why should those conditions stay the same?', questions: [
      mc('A green ink dot makes yellow and blue bands. What does this support?', ['The water made new colors.', 'The ink contained at least two dyes.', 'Every green material is a mixture.'], 1, 'The bands support the claim that this ink contains different dyes. This experiment does not establish a rule about all green materials.'),
      write('An invented experiment gives these distances after 8 minutes: yellow dye 5 cm, blue dye 2 cm. Describe the evidence and explain the separation.', 'The yellow dye traveled 3 cm farther. The dyes interacted differently with the water and paper, so the moving water carried them different distances. The distances alone do not tell us molecule sizes.'),
      write('Draw a model of the ink before and after separation. What must stay the same?', 'Use a key for two particle types. Mix both types together before separation and show them in separate bands afterward. Keep the same numbers and kinds of particles: separation does not create or destroy the dyes.')
    ] },
    { id: 'matter-2', title: 'Chapter 2 · Dissolving and sediment', focus: 'Where does a solid go when it dissolves?', read: [
      'When a little salt dissolves in water, we stop seeing the salt grains. The salt is still present as tiny particles spread through the water. Dissolving is not melting: the solid did not need to become a liquid salt puddle. Some materials dissolve readily in water; others, such as sand, do not.',
      'Solubility describes how much of a material can dissolve under given conditions. Stirring can help a material dissolve faster, but it cannot make an unlimited amount dissolve. Undissolved particles may settle to the bottom as sediment. A filter can catch sand grains but an ordinary coffee filter will not remove dissolved salt.'
    ], vocabulary: [['dissolve', 'To spread through a liquid as particles too small to see individually.'], ['solution', 'A mixture with dissolved material distributed through it.'], ['solubility', 'How much of a substance can dissolve under given conditions.'], ['sediment', 'Undissolved material that settles.']], activity: 'With an adult, compare a small pinch of salt and a small pinch of clean sand in separate clear cups with equal amounts of room-temperature water. Stir each equally and observe. Label cups and do not taste. Draw what you see and what you infer about particles.', coach: 'Use the sentence frame: “I cannot see the grains anymore, but I think ___ because ___.” For a sealed salt-and-water container, ask what a scale should show before and after mixing.', misconception: 'Dissolved matter has not disappeared or become water. A clear mixture can still contain dissolved substances.', stretch: 'Plan how to test whether water temperature changes dissolving speed. An adult handles warm water; use no boiling water.', questions: [
      mc('Salt dissolves in a sealed cup of water. What happens to the total mass?', ['It decreases because salt vanished.', 'It increases because particles multiply.', 'It stays the same if nothing enters or leaves.'], 2, 'All the original matter remains in the sealed cup; changing its distribution does not change the total mass.'),
      write('Invented results: salt is no longer visible after stirring; sand remains and later settles. Which would leave sediment, and why?', 'The sand would leave sediment because it stayed undissolved and settled. The salt is still there, spread through the water at a scale too small to see.'),
      write('How could you separate sand and dissolved salt from water?', 'Filter the sand first. An adult could then let the water evaporate to recover salt. A coffee filter alone would not catch the dissolved salt. Do not drink the mixture.')
    ] },
    { id: 'matter-3', title: 'Chapter 3 · Keeping liquids mixed', focus: 'Why does salad dressing separate after shaking?', read: [
      'Shaking oil and water breaks the oil into small droplets. For a short time the droplets are scattered, but they can join together again and form a layer. In a simplified particle model, attractions within each liquid help explain why these liquids separate. A model explains a pattern without showing every detail of real molecules.',
      'An emulsifier can help droplets stay dispersed for longer. Part of an emulsifier interacts well with water and another part interacts well with oil. A stable-looking dressing is not necessarily a solution: tiny oil droplets may still be present. Fair comparisons need the same ingredient amounts, shaking time, temperature, and observation times.'
    ], vocabulary: [['emulsion', 'A mixture with droplets of one liquid dispersed in another.'], ['emulsifier', 'A material that helps liquids such as oil and water stay dispersed.'], ['attraction', 'An interaction that tends to draw particles together.'], ['stable', 'Remaining relatively unchanged over the time being studied.']], activity: 'An adult seals two plastic containers with equal small amounts of water and oil. Add a little mustard to one only, checking allergies before handling it. Shake both equally. Compare after 1, 5, and 10 minutes. Do not taste; mixtures can vary, so record actual results.', coach: 'Ask for a prediction first. Then ask: “What changed? What stayed the same? What evidence would make you revise your idea?” Explain that an emulsifier helps mixing last; it does not guarantee it will last forever.', misconception: 'Shaking alone does not permanently dissolve oil in water. The top layer’s position and the reason liquids do not mix are different questions.', stretch: 'Design a table for the height of the separated layer over time. Which result would support an emulsifier helping?', questions: [
      mc('Which comparison best tests an emulsifier?', ['Change the emulsifier and keep other conditions alike.', 'Use different liquids, amounts, and shaking times.', 'Observe only the container with emulsifier.'], 0, 'Changing one factor makes it easier to connect differences in separation to that factor.'),
      write('Invented results: after 10 minutes jar A has a 2 cm oil layer; jar B with emulsifier has a 0.5 cm layer. What claim is supported?', 'Under these test conditions, jar B separated less. The emulsifier helped the mixture remain dispersed longer. One observation does not prove it will never separate.'),
      write('Describe a particle or droplet model explaining the emulsifier.', 'Show oil droplets surrounded by water. Add emulsifier symbols at the boundaries, with one part interacting with oil and another with water. Explain that this helps keep droplets from joining together. Include a key and identify that the drawing is simplified.')
    ] },
    { id: 'matter-4', title: 'Section 4 · Home review and design challenge', focus: 'Can you explain a mixture using observations and a model?', read: [
      'Food scientists connect visible evidence to an explanation about invisible particles. Start with a claim, describe specific observations, and explain why those observations support the claim. A good model has a key and shows the important relationships. We revise it when new evidence does not fit.',
      'Here is an invented dressing test: each jar contains 40 mL water, 10 mL oil, and a pinch of salt. Both are shaken for 20 seconds. Jar A has no emulsifier and forms a clear oil layer after 2 minutes. Jar B has mustard and has only a thin oil layer after 10 minutes. No salt grains are visible in either. These are practice data, not guaranteed experiment results.'
    ], vocabulary: [['claim', 'An answer or conclusion.'], ['evidence', 'Observations or measurements used to support a claim.'], ['reasoning', 'How evidence and scientific ideas connect to a claim.']], activity: 'Make a one-page food-scientist report using the invented data above. Include a claim, two pieces of evidence, a particle-model key, and one next test. Explain it aloud in two minutes.', coach: 'Use three sessions for Chapters 1–3, then this review on a fourth day. Begin each session with a two-minute recall from the previous lesson. Have your child revise an answer after comparing with the model answer.', misconception: 'A claim is not stronger just because it sounds confident. It needs relevant evidence and a logical explanation.', stretch: 'Could the salt change separation? Propose a separate fair test rather than changing several factors at once.', questions: [
      mc('Which statement best fits the invented test?', ['Mustard removed the oil.', 'Mustard helped oil stay dispersed longer in this test.', 'Salt became water.'], 1, 'Jar B had less visible separation at a later observation time. This supports improved stability, not disappearance of the oil.'),
      write('Explain both the invisible salt and the oil layer in jar A.', 'The salt dissolved and its particles spread through the water. Oil remained a different liquid; droplets joined after shaking and formed a layer. Invisible salt is still matter, and a visible layer does not mean new oil was made.'),
      write('Give one limit of the evidence and one useful next test.', 'We tested only one amount of mustard and did not repeat trials. Repeat the comparison with equal observation times and several trials, or vary only the amount of mustard in a new experiment.')
    ] }
  ] },
  { id: 'sky', subject: 'science', title: 'Patterns of Earth and Sky', label: 'Unit 1', status: 'Review', description: 'Review stars, day and night, and patterns across the year.', sources: ['amplify', 'nasa'], lessons: [
    { id: 'sky-1', title: '1 · The Sun is a nearby star', focus: 'Why does the Sun look so much brighter?', read: ['The Sun is a star. Other stars can be enormous, but they are much farther away. Distance affects how bright an object appears. A nearby light may look brighter than a more powerful distant light.', 'During daytime, sunlight scattered through the atmosphere makes the sky bright. Other stars are still in space even when we cannot see them. Never look directly at the Sun or point binoculars toward it.'], vocabulary: [['star', 'A hot object in space that produces its own light.'], ['apparent brightness', 'How bright something looks from where you observe it.']], activity: 'In a dim room, an adult holds the same small flashlight at two distances from a wall. Compare the spot of light without shining it into anyone’s eyes. Discuss what this model leaves out about stars.', coach: 'Ask your child to separate “looks brighter” from “produces more light.” Use the same light to isolate distance.', misconception: 'A brighter-looking star is not always a larger star. Apparent brightness also depends on distance.', stretch: 'Why would comparing two different flashlights be a less fair distance test?', questions: [mc('Why does the Sun appear much brighter than other stars?', ['It is much closer to Earth.', 'It is the only star producing light.', 'Other stars turn off during daytime.'], 0, 'The Sun is far closer than other stars.'), write('Why can stars be in the sky without being visible during the day?', 'The bright daytime sky makes faint starlight difficult to see. The stars have not gone away.'), write('Name one limit of a flashlight model.', 'A flashlight is not a star and does not produce light in the same way. It can illustrate a distance effect without representing a star’s actual size or processes.')] },
    { id: 'sky-2', title: '2 · Rotation and daily patterns', focus: 'Why do we have day and night?', read: ['Earth rotates, or spins, roughly once every 24 hours. The side facing the Sun has daytime; the side facing away has nighttime. As your location turns, the Sun appears to move across the sky.', 'At night, stars also appear to change position over hours because Earth turns. A shadow can change length and direction during a day as the Sun’s apparent position changes.'], vocabulary: [['rotation', 'The spinning of an object around an axis.'], ['axis', 'An imaginary line through a spinning object.']], activity: 'Use a ball with a sticker for your location and a stationary flashlight for the Sun. Turn the ball slowly. Stop when the sticker enters and leaves the light.', coach: 'Keep the light still and ask which object’s motion causes the sticker’s day and night. Ask for a drawing from above.', misconception: 'Day and night do not require the Sun to travel around Earth once each day.', stretch: 'Explain why a person on the opposite side of the ball has a different experience at the same moment.', questions: [mc('What mainly explains daily sunrise and sunset?', ['Earth rotates.', 'Earth completes its yearly orbit every day.', 'The Sun turns off.'], 0, 'Earth’s rotation turns a location toward and then away from sunlight.'), write('Invented observations: a star is near a tree at 8 pm and farther west at 10 pm. What motion can explain this?', 'Earth rotated during those two hours, changing the direction the observer faced in space.'), write('Use the ball model to explain night.', 'The sticker is on the side turned away from the light. The ball blocks direct light from reaching it.')] },
    { id: 'sky-3', title: '3 · Orbit and yearly star patterns', focus: 'Why can we see different stars in different months?', read: ['Earth orbits the Sun about once each year while also rotating each day. At different places in the orbit, Earth’s nighttime side faces different directions in space. This helps explain why some constellations are visible in one season and not another.', 'A constellation is a pattern of stars seen from Earth; its stars may be very far from each other. A pattern recorded at the same hour in different months can provide evidence of a yearly change. The daily and yearly patterns need different timescales of observations.'], vocabulary: [['orbit', 'The path an object follows around another object.'], ['constellation', 'A named pattern or region of stars as seen from Earth.']], activity: 'Put star-pattern cards around a room and a lamp in the center. Move a ball around the lamp and ask which cards face the ball’s nighttime side. Do not stare into the lamp.', coach: 'Ask “Over hours or over months?” before deciding whether to explain a pattern with rotation or orbit.', misconception: 'Yearly visibility changes do not mean all the stars move around Earth once a year.', stretch: 'How would you plan observations at the same location and time over several months?', questions: [mc('Which motion helps explain different nighttime stars across the year?', ['Earth’s yearly orbit.', 'Clouds creating new stars.', 'Earth stopping its rotation.'], 0, 'Earth’s nighttime side points toward different regions of space as Earth orbits the Sun.'), write('Explain the difference between rotation and orbit.', 'Rotation is Earth spinning on its axis, about once per day. Orbit is Earth moving around the Sun, about once per year.'), write('A sky drawing is missing a piece. What evidence would help predict the missing stars?', 'Compare complete sky records from the same location, season, viewing direction, and time of night. Use the repeated pattern and explain uncertainty rather than simply guessing.')] }
  ] },
  { id: 'earth', subject: 'science', title: 'The Earth System', label: 'Unit 3', status: 'Preview', description: 'Explore water shortages, water movement, and interacting Earth systems.', note: 'Preview based on Amplify’s recommended sequence. The newsletters do not yet confirm the next unit title or teaching dates. These are home lesson sections, not official chapter numbers.', sources: ['sequence', 'water', 'snow'], lessons: [
    { id: 'earth-1', title: '1 · Where is usable water?', focus: 'Why can a watery planet have water shortages?', read: ['Most Earth water is salty ocean water. Much freshwater is frozen or underground, and not all is easy to access safely. A shortage can happen when accessible water does not meet the needs of people and ecosystems.', 'Earth’s systems interact: the hydrosphere includes water; the atmosphere is the air; the geosphere includes rocks and soil; the biosphere includes living things. A tree drawing water from soil connects several systems.'], vocabulary: [['freshwater', 'Water with relatively little dissolved salt.'], ['hydrosphere', 'Earth’s water in all its forms and locations.'], ['system', 'Interacting parts that form a whole.']], activity: 'Draw a local landscape and label air, rocks and soil, living things, and water. Add arrows showing two interactions.', coach: 'Ask about access, water quality, and timing, not just the total amount of water on Earth.', misconception: 'An ocean nearby does not automatically provide drinkable water; removing salt takes equipment and energy.', stretch: 'Compare a solution for polluted water with a solution for a dry season. Are they the same problem?', questions: [mc('Which is an interaction between the biosphere and hydrosphere?', ['A tree takes in water.', 'Two dry rocks sit together.', 'An empty notebook is closed.'], 0, 'The tree is living and the water belongs to the hydrosphere.'), write('Why does “Earth has lots of water” not rule out a shortage?', 'Much water is salty, frozen, polluted, hard to reach, or unavailable when and where it is needed.'), write('Name two questions to ask before choosing a water solution.', 'How much accessible freshwater is available? Who and what needs it? Is the main problem timing, pollution, distribution, or a lack of supply? Any two relevant questions work.')] },
    { id: 'earth-2', title: '2 · Water moves through systems', focus: 'How does water move from the ground to clouds and back?', read: ['Energy from sunlight can cause liquid water to evaporate into invisible water vapor. Cooling can cause vapor to condense into liquid droplets. Clouds contain tiny droplets or ice crystals. Precipitation returns water to the surface.', 'Water can run downhill, soak into soil, enter groundwater, freeze, melt, and move through living things. The water cycle has many possible paths, not one required starting point.'], vocabulary: [['evaporation', 'Liquid water becoming water vapor.'], ['condensation', 'Water vapor becoming liquid water.'], ['precipitation', 'Water falling from clouds, such as rain or snow.'], ['infiltration', 'Water soaking into the ground.']], activity: 'With an adult, observe droplets outside a cold cup. Dry the outside first. Explain why new droplets can appear without water leaking through the cup.', coach: 'Have your child trace one possible water path with arrows. Ask where energy and gravity affect the movement.', misconception: 'Clouds are not made only of invisible water vapor. Their visible parts include tiny liquid droplets or ice crystals.', stretch: 'Why could paving over soil change runoff and groundwater recharge?', questions: [mc('Droplets form outside a cold cup. Which process explains them?', ['Condensation from air.', 'Water passing through solid plastic.', 'Creation of new matter.'], 0, 'Water vapor in nearby air cools and condenses on the outside surface.'), write('Trace a possible path from ocean to river.', 'Ocean water evaporates, vapor moves in air, water condenses into clouds, precipitation falls on land, and runoff or groundwater carries water toward a river.'), write('Why does the water cycle not need a single starting place?', 'Water is continually moving among many stores and can follow different routes. A cycle does not have a required beginning.')] },
    { id: 'earth-3', title: '3 · Mountains and water solutions', focus: 'How can land shape rainfall and water access?', read: ['Moist air forced up a mountain can cool and release precipitation. Air descending on the other side can be drier. This rain-shadow pattern helps explain why nearby places sometimes receive different amounts of rain.', 'Water solutions have benefits and tradeoffs. Repairing leaks reduces losses; reservoirs store water; protecting watersheds supports water quality. A plan needs evidence about supply, demand, cost, and effects on other living things.'], vocabulary: [['rain shadow', 'A drier region on the downwind side of mountains.'], ['watershed', 'Land area draining to a shared outlet.'], ['tradeoff', 'A cost or drawback that comes with a benefit.']], activity: 'Draw wind arrows across a mountain. Label rising moist air, precipitation, and descending drier air. Then compare two proposed water solutions.', coach: 'Use a claim–evidence–reasoning explanation, then ask who benefits and who might bear the cost.', misconception: 'Mountains do not simply act like walls that stop all clouds; rising and cooling air are part of the explanation.', stretch: 'What data would help decide between repairing leaks and building new storage?', questions: [mc('Where is a rain shadow commonly found?', ['On the drier downwind side.', 'Always on the wettest side.', 'Inside every reservoir.'], 0, 'Air can lose moisture while rising and then descend drier on the downwind side.'), write('Invented data: town A receives 80 cm rain/year; town B across the mountain gets 20 cm. Is that enough to prove a rain shadow?', 'It supports a rainfall difference. Wind direction and evidence of air rising and cooling would strengthen a rain-shadow explanation. Other factors could also affect rainfall.'), write('Give a benefit and a tradeoff of a reservoir.', 'A reservoir can store water for dry times. It can also change river habitats, block movement of fish, flood land, and cost money. A strong plan considers both.')] }
  ] },
  { id: 'ecosystems', subject: 'science', title: 'Ecosystem Restoration', label: 'Unit 4', status: 'Preview', description: 'Follow matter and energy through living systems and design a restoration plan.', note: 'Preview based on the publisher’s recommended sequence; school timing is unconfirmed. The sections here are original home lessons.', sources: ['sequence', 'plants', 'amplify'], lessons: [
    { id: 'eco-1', title: '1 · What plants need to grow', focus: 'Where does a growing plant get its matter?', read: ['Plants use light energy to make sugars from water and carbon dioxide in a process called photosynthesis. Those sugars provide material and stored energy. Much of a plant’s dry mass comes from carbon dioxide taken from the air, not from eating soil.', 'Roots take in water and mineral nutrients. Light supplies energy; it is not matter. A plant can fail to thrive when a needed resource is missing, even if other resources are abundant.'], vocabulary: [['photosynthesis', 'Using light energy to make sugars from water and carbon dioxide.'], ['resource', 'Something an organism needs or uses.']], activity: 'Sketch a plant with labeled arrows for light, carbon dioxide, and water entering. Label light as energy and the other two as matter.', coach: 'Ask “Is this matter or energy?” for each arrow. Keep nutrients important without describing soil as the main source of plant mass.', misconception: 'Sunlight is not a material that adds mass, and soil is not food in the same sense as sugar.', stretch: 'Plan a light investigation that keeps plant type, water, soil, and temperature alike.', questions: [mc('Which supplies energy for photosynthesis?', ['Sunlight.', 'Soil particles.', 'A flowerpot.'], 0, 'Light supplies energy. Water and carbon dioxide supply matter used to make sugars.'), write('Why can a watered plant still grow poorly in a dark room?', 'Water is only one need. With too little light, photosynthesis cannot provide enough sugar for healthy growth.'), write('Where does much of a plant’s dry mass come from?', 'Carbon dioxide from air supplies carbon for the sugars and other materials the plant builds. Water also contributes matter; mineral nutrients are needed in smaller amounts.')] },
    { id: 'eco-2', title: '2 · Food webs, matter, and energy', focus: 'How are organisms connected?', read: ['A food-web arrow usually points from food to the organism eating it, showing transfer of matter and energy. In an example web, leaves feed insects, insects feed birds, and dead material supports decomposers such as fungi.', 'Matter can be reused through an ecosystem. Energy flows through it and much eventually spreads into the surroundings as heat. Decomposers help recycle nutrients; they do not return used energy to the Sun.'], vocabulary: [['producer', 'An organism that makes its own food, often using sunlight.'], ['consumer', 'An organism that gets food by eating other organisms or their parts.'], ['decomposer', 'An organism that breaks down dead material and wastes.']], activity: 'Draw leaves → insect → bird, then dead material → fungus. Explain every arrow aloud before adding more connections.', coach: 'Have your child trace both matter and energy. Ask why a bird could be affected by a change in plants even if it eats insects.', misconception: 'Energy does not cycle in the same way matter does. Food webs also include decomposers, not only large animals.', stretch: 'Why can removing one organism have more than one effect in a food web?', questions: [mc('In leaves → insect, what does the arrow mean?', ['The insect receives matter and energy from leaves.', 'The leaf eats the insect.', 'Only water moves.'], 0, 'The arrow follows transfer from food to the eater.'), write('What might happen to insect-eating birds if many food plants die?', 'There may be less food for insects, fewer insects, and less food for birds. This is a prediction that should be checked with observations.'), write('How do decomposers help an ecosystem?', 'They break down dead material and wastes, returning nutrients to the environment where other organisms can use them.')] },
    { id: 'eco-3', title: '3 · Build an evidence-based restoration plan', focus: 'How do we decide what a damaged ecosystem needs?', read: ['Restoration means helping an ecosystem recover. First identify a problem, gather evidence, and compare possible explanations. A population may decline because of habitat loss, missing food, water changes, disease, or several causes together.', 'Invented study: in a disturbed forest patch there are few young trees, little leaf cover, few leaf-eating insects, and few insect-eating birds. Nearby protected patches have more of all four. Replanting suitable native trees is one possible action, but we still need to check water, soil, and survival over time.'], vocabulary: [['restoration', 'Actions intended to help an ecosystem recover.'], ['monitor', 'Observe or measure repeatedly over time.']], activity: 'Write a restoration proposal for the invented forest. Include the problem, evidence, one action, one alternative explanation, and a monitoring plan.', coach: 'Ask “What would we measure later to learn whether our action worked?” Encourage revising the plan rather than promising an instant fix.', misconception: 'Adding animals alone may not help if the habitat and food resources they need are missing.', stretch: 'How could you compare a restored patch with a similar untreated patch fairly?', questions: [mc('What should come before selecting an action?', ['Gather evidence about the problem.', 'Assume every forest needs more predators.', 'Stop observing.'], 0, 'Evidence helps connect an action to a likely cause.'), write('Use the invented forest observations to explain why planting trees might help birds.', 'More surviving trees could provide leaves for insects, which could provide food for birds. The observed pattern supports this possibility but does not prove it is the only cause.'), write('Give two measurements for monitoring the plan.', 'Measure seedling survival and leaf cover, insect counts, or bird observations using consistent methods and seasons. Compare over time and with a suitable reference patch.')] }
  ] },
  { id: 'california', subject: 'social', title: 'Stewards of Our State', label: 'Inquiry 1', status: 'Review & finish', description: 'California regions, Indigenous communities, water scarcity, and a brochure project.', note: 'Aligned to the September–December 2026 classroom newsletter topics. The readings, practice data, and questions are original home-study materials.', sources: ['regions', 'ramaytush', 'water', 'snow', 'missions'], lessons: [
    { id: 'ca-1', title: '1 · Regions and Indigenous California', focus: 'How do people interact with California’s varied environments?', read: ['A common classroom model groups California into coast, mountains, Central Valley, and deserts. These regions have different patterns of water, climate, landforms, and resources. A model simplifies a landscape; real boundaries and local conditions are more complicated.', 'California is home to many distinct Indigenous nations with their own languages, knowledge, and histories. Communities adapted to local environments and actively managed land and resources. Native peoples continue to live here and care for their communities and lands. Avoid treating many nations as a single culture.'], vocabulary: [['region', 'An area grouped by shared characteristics.'], ['Indigenous', 'Connected to peoples whose communities have long-standing ties to a place before colonization.'], ['stewardship', 'Caring responsibly for land, water, and communities.']], activity: 'On a California outline map, label the four classroom regions. Add one water or landform observation per region. Use a resource from a specific tribal nation when researching that nation’s history.', coach: 'Ask “Which nation? Which place? Which time?” Encourage present-tense language as well as historical examples.', misconception: 'California was not empty before European settlement, and Indigenous peoples are not only people of the past.', stretch: 'How could two maps divide California differently and still be useful?', questions: [mc('Which statement is most accurate?', ['All Native Californian nations share one culture.', 'Many distinct Indigenous nations have histories and continuing communities here.', 'People never changed California landscapes before colonization.'], 1, 'Distinct nations have different languages, histories, and traditions and continue today.'), write('How could water availability affect life in two regions?', 'A dry desert may require careful use of limited water, while coastal or mountain locations have different seasonal sources. Specific examples should use evidence about the places being compared.'), write('What should you include when presenting research about an Indigenous nation?', 'Name the specific nation and place, use reliable sources including that nation’s own materials when possible, distinguish past from present, and avoid generalizing to all Native people.')] },
    { id: 'ca-2', title: '2 · Scarcity and water management', focus: 'How do communities make choices when water is limited?', read: ['Scarcity means available resources do not meet all wants and needs. California water is unevenly distributed across places and seasons. Mountain snow can store winter precipitation and release it as it melts. Reservoirs, pipes, and canals can store or move water, but supply is still limited.', 'Homes, farms, businesses, and ecosystems all depend on water. Choosing one use can reduce what remains for another. Water management needs evidence about needs, conservation, fairness, cost, and environmental effects. Rivers need water too; not all water in a river is unused.'], vocabulary: [['scarcity', 'A condition in which available resources cannot meet every want or need.'], ['infrastructure', 'Systems such as pipes, canals, and reservoirs.'], ['conservation', 'Using resources carefully and reducing avoidable waste.']], activity: 'Use 10 counters as an invented town’s water budget. Requests are: homes 3, farms 5, river habitat 3, parks 1. Allocate the 10 counters, explain tradeoffs, and propose a way to reduce demand.', coach: 'Ask who is affected by each choice. Separate a made-up budget from real California measurements.', misconception: 'Moving or storing water does not create unlimited new water or remove every environmental cost.', stretch: 'How might earlier snowmelt change when storage or conservation is needed?', questions: [mc('The requests total 12 counters but only 10 are available. This shows:', ['Scarcity.', 'Unlimited supply.', 'No need to make choices.'], 0, 'The available supply cannot satisfy all requests at once.'), write('Give a reason California may need to store or move water.', 'Water may arrive during wet months or in places far from demand. Storage and transportation can help match supply to needs, while introducing costs and environmental effects.'), write('Propose a response to the counter-budget shortage and explain a tradeoff.', 'For example, reduce avoidable waste and change park irrigation so more water remains for essential uses and habitat. Some choices may cost money or change how public spaces look. Other justified allocations are acceptable.')] },
    { id: 'ca-3', title: '3 · Stewardship and the California brochure', focus: 'How can a brochure persuade using evidence?', read: ['A stewardship brochure teaches a reader about a place and recommends an informed action. Useful sections include California regions, a specific Indigenous community, a water challenge, a management approach, and an action the reader can take.', 'Use a claim, evidence, and an explanation. Credit sources and label images or maps. Distinguish a historical fact from an opinion. Stewardship includes learning from people with long relationships to a place and considering whose voices are missing. For a local example, the Ramaytush Land Trust describes caring for ancestral lands through restoration, service, and cultural revitalization. This is an example to research, not a claim about which steward your teacher assigned.'], vocabulary: [['source', 'Where information comes from.'], ['informed action', 'A decision or action based on relevant evidence.']], activity: 'Make a six-panel brochure: cover and question; regions; a specific Indigenous nation; water scarcity; management and tradeoffs; a realistic action plus sources. Use your classroom research for the environmental steward your teacher assigned; the newsletters do not name a particular person.', coach: 'Check each factual claim against a source. Ask for an action someone can actually take, such as reporting leaks, and a clear reason it helps.', misconception: 'A colorful brochure still needs accurate evidence and source credits. A slogan alone is not an explanation.', stretch: 'Add the perspective of a farmer, tribal community, city resident, or habitat scientist. Explain why their concerns may differ.', questions: [mc('Which claim is most useful for an evidence-based brochure?', ['Water is important because I say so.', 'Reporting leaks reduces avoidable loss of treated water.', 'California never has water challenges.'], 1, 'It identifies a specific action and explains the connection to conservation.'), write('Write a short brochure paragraph recommending one action.', 'Example: Report a leaking school faucet to an adult. A leak lets treated water run without meeting a need. Repairing it can conserve water for people and other uses. Add evidence from a reliable source if giving a numerical estimate.'), write('How would you check whether your brochure is ready?', 'Check accurate facts, a labeled map, respectful and specific descriptions of people, a water problem and response, a tradeoff, an achievable action, and credits for sources and images.')] }
  ] },
  { id: 'history', subject: 'social', title: 'From Territory to Golden State', label: 'Inquiry 2', status: 'Up next', description: 'Explore missions, Mexican rule, the Gold Rush, statehood, and whose perspectives are heard.', note: 'The November–December newsletter confirms these topics. The five sections below are a home-study sequence, not a confirmed classroom lesson calendar.', sources: ['missions', 'timeline', 'gold', 'state', 'government'], lessons: [
    { id: 'history-1', title: '1 · Spanish missions and Native perspectives', focus: 'How did the mission system change life in California?', read: ['Spanish colonization expanded in Alta California in the late 1700s. Missions were religious and economic institutions that supported Spanish control. Mission communities raised crops and livestock and changed land use.', 'For many Native people the system brought forced labor, restrictions on movement and cultural practices, disease, and loss of land. Native people resisted, adapted, and maintained ties and traditions. Buildings alone cannot tell the whole history; accounts from Native communities are essential.'], vocabulary: [['colonization', 'A process in which an outside power takes control of land and people.'], ['mission', 'A religious settlement that also served colonial purposes.'], ['perspective', 'A viewpoint shaped by a person’s experiences and position.']], activity: 'Make a two-column chart: the goals of Spanish colonizers, and effects on Native communities. Add a question you would ask of a source from each perspective.', coach: 'Be direct about coercion and loss without graphic detail. Ask whose choices were restricted and whose account a source represents.', misconception: 'Missions were not simply helpful schools that all Native people freely chose to join.', stretch: 'What would a building inventory tell us, and what might it leave out about people’s experiences?', questions: [mc('Why use Native accounts alongside Spanish records?', ['To understand experiences Spanish records may leave out.', 'Because all sources always agree.', 'To remove the need for evidence.'], 0, 'Different sources can reveal unequal power and experiences not fully described by colonial records.'), write('Name one colonial goal and one effect on Native communities.', 'Spain sought religious conversion and territorial control. Effects on many Native communities included lost land, coerced labor, disease, and restrictions on cultural practices.'), write('Why is “everyone benefited” a weak description of missions?', 'It ignores unequal power and documented harms. An explanation needs to identify who gained control and who lost land, freedom, or cultural protections.')] },
    { id: 'history-2', title: '2 · Mexican rule and ranchos', focus: 'What changed after Mexico gained independence?', read: ['Mexico gained independence from Spain in 1821, and Alta California came under Mexican rule. Ranchos were large landholdings often focused on cattle. Californios developed communities, trade, and ranching traditions.', 'During secularization in the 1830s, mission lands and property were transferred out of church control. Many Native people did not receive the lands they had been promised; much went to powerful landholders. A change in government did not automatically mean equal rights or restored land for everyone.'], vocabulary: [['rancho', 'A large ranch or landholding.'], ['Californio', 'Often used for Spanish-speaking residents of California during the Spanish and Mexican eras and their descendants.'], ['secularization', 'Transfer of institutions or property from religious to civil control.']], activity: 'Add 1821 and the 1830s to a timeline. Write one change and one continuing inequality next to each.', coach: 'Compare political control with daily life. Ask who could own land, make decisions, and benefit from ranching.', misconception: 'Mexican independence did not instantly return all mission lands to Indigenous communities.', stretch: 'How might a wealthy ranchero and a Native worker describe the same rancho differently?', questions: [mc('Who governed Alta California after Mexican independence in 1821?', ['Mexico.', 'The United States immediately.', 'No government.'], 0, 'Alta California became part of independent Mexico.'), write('What was secularization, and why did outcomes differ among people?', 'It moved mission property out of church control. Powerful landholders obtained much of the land, while many Native people did not receive promised land.'), write('Give one change and one continuity from Spanish to Mexican rule.', 'Political authority shifted from Spain to Mexico and ranchos grew in importance. Unequal power and loss of Indigenous land continued.')] },
    { id: 'history-3', title: '3 · Gold Rush: opportunity and harm', focus: 'How did the Gold Rush affect different communities?', read: ['Gold was discovered at Sutter’s Mill in 1848. News drew many migrants in 1849 and later. Some sought gold; others supplied food, tools, lodging, and transport. Many miners did not become wealthy, and prices could be high.', 'The Gold Rush transformed communities and landscapes. Mining could damage rivers, while Native people faced violent displacement and destruction of livelihoods. Chinese and other immigrant miners also faced discrimination. Evaluate both opportunities and harms rather than telling a story of success for everyone.'], vocabulary: [['migration', 'Movement of people from one place to another.'], ['discrimination', 'Unfair treatment based on identity or group membership.'], ['cause and effect', 'A relationship between an event and what it helps bring about.']], activity: 'Create three viewpoint cards: a miner, a shopkeeper, and a Native community member. For each, write a possible change and a question requiring more evidence. These cards are imagined, not historical quotations.', coach: 'Distinguish a possible viewpoint from a documented first-person account. Ask how the same event could bring income to one person and harm another.', misconception: 'Finding gold did not guarantee wealth, and California was already home to people before the rush.', stretch: 'Why might a store owner earn money even if nearby miners found little gold?', questions: [mc('Which is a plausible effect of rapid migration?', ['Greater demand for food and housing.', 'No change in local communities.', 'Guaranteed wealth for every miner.'], 0, 'More people can increase demand for supplies, homes, and services.'), write('Give two different effects of the Gold Rush.', 'It created some opportunities in mining and supply businesses, and it also caused displacement, discrimination, and environmental damage. Explain which people or places were affected.'), write('How would you check a claim that a miner became rich?', 'Look for evidence such as letters, records of earnings, and costs. Compare independent sources and avoid assuming one successful person represents everyone.')] },
    { id: 'history-4', title: '4 · California becomes a state', focus: 'How did California become part of the United States?', read: ['After the U.S.–Mexican War, the 1848 Treaty of Guadalupe Hidalgo transferred a large region including California to the United States. Gold Rush migration rapidly increased the settler population. California entered the Union on September 9, 1850, as the 31st state.', 'California was admitted as a free state in the national conflict over slavery, but this did not mean equal rights for all residents. Native peoples and other communities faced discriminatory laws and exclusion. Political statehood and equality are separate questions.'], vocabulary: [['treaty', 'A formal agreement between governments.'], ['statehood', 'The status of being a state within a country.'], ['constitution', 'A basic framework for government.']], activity: 'Build a timeline: 1821 Mexican independence → 1848 treaty and gold discovery → 1849 large migration → 1850 statehood. Add one sentence connecting two events.', coach: 'Avoid suggesting the Gold Rush alone transferred California from Mexico. Separate the war and treaty from the population growth that followed.', misconception: '“Free state” did not mean every resident had equal freedom, rights, or political power.', stretch: 'Why is a timeline useful but not sufficient to prove that one event caused another?', questions: [mc('Which event came last?', ['Mexican independence in 1821.', 'Gold discovery in 1848.', 'California statehood in 1850.'], 2, 'California became the 31st state on September 9, 1850.'), write('Explain two different developments on the path to statehood.', 'The war and 1848 treaty transferred control to the United States. Gold Rush migration increased the settler population and helped accelerate the move toward statehood.'), write('Why should a statehood account discuss unequal rights?', 'Statehood changed government but did not give equal treatment to everyone. Including excluded communities makes the account more accurate.')] },
    { id: 'history-5', title: '5 · Evidence, government, and a history review', focus: 'How do we build a fair explanation of change?', read: ['A primary source comes from the time or event being studied, such as a diary or law. A secondary source interprets the past, such as a later history article. Both require questions: who made it, when, for whom, and what might it leave out?', 'A legislature makes laws. California has an Assembly and a Senate; the U.S. Congress has a House of Representatives and a Senate. Voting helps eligible people choose representatives and decide measures. Studying who could vote at different times helps us see that political participation has not always been equal.'], vocabulary: [['primary source', 'Evidence created during the time or event being studied.'], ['secondary source', 'A later account that interprets or explains events.'], ['legislature', 'The part of government that makes laws.']], activity: 'Sort these examples: an 1849 diary, a modern museum article about 1849, and an 1850 law. Then write a paragraph answering: “How did California change, and for whom?” Include two periods and two perspectives.', coach: 'Use a four-point home rubric: accurate sequence, specific evidence, more than one perspective, and clear reasoning. Discuss missing evidence rather than treating one account as complete.', misconception: 'A primary source is not automatically unbiased or correct. A person can describe only part of an event.', stretch: 'Compare how two sources describe the same law. What evidence supports each interpretation?', questions: [mc('Which is a primary source for the Gold Rush?', ['An 1849 diary written by someone there.', 'A recent textbook chapter.', 'A newly written fictional story.'], 0, 'A diary from that period can provide firsthand evidence, while still reflecting its author’s limited viewpoint.'), write('What does a legislature do? Name California’s two chambers.', 'A legislature makes laws. California’s chambers are the State Assembly and State Senate.'), write('Explain California’s changes from missions to statehood using more than one perspective.', 'A strong answer sequences Spanish missions, Mexican rule, the 1848 transfer, Gold Rush, and 1850 statehood. It explains opportunities or power gained by some groups and land loss, coercion, discrimination, or exclusion experienced by others, using specific evidence.')] }
  ] }
];
